--
-- Table structure for table `purchase_agreements`
--

DROP TABLE IF EXISTS `purchase_agreements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `purchase_agreements` (
  `id` int NOT NULL AUTO_INCREMENT,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `seller_user_id` int NOT NULL,
  `seller_company_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seller_address` text COLLATE utf8mb4_unicode_ci,
  `seller_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seller_contact_person` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seller_is_legal_owner` tinyint(1) DEFAULT NULL,
  `buyer_full_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `buyer_date_of_birth` date DEFAULT NULL,
  `buyer_address` text COLLATE utf8mb4_unicode_ci,
  `buyer_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vehicle_id` int DEFAULT NULL,
  `make` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `engine_displacement` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `power` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transmission` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vin` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stammnummer` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type_approval_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `first_registration_date` date DEFAULT NULL,
  `mileage` int DEFAULT NULL,
  `last_mfk_date` date DEFAULT NULL,
  `purchase_price` decimal(12,2) DEFAULT NULL,
  `second_key_available` tinyint(1) DEFAULT NULL,
  `accident_free` tinyint(1) DEFAULT NULL,
  `vehicle_remarks` text COLLATE utf8mb4_unicode_ci,
  `defects_known` tinyint(1) DEFAULT NULL,
  `defect_remarks` text COLLATE utf8mb4_unicode_ci,
  `service_book_available` tinyint(1) DEFAULT NULL,
  `service_book_remarks` text COLLATE utf8mb4_unicode_ci,
  `warranty_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `warranty_other_text` text COLLATE utf8mb4_unicode_ci,
  `payment_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_other_text` text COLLATE utf8mb4_unicode_ci,
  `handover_date` date DEFAULT NULL,
  `handover_location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pa_seller_user_id` (`seller_user_id`),
  KEY `idx_pa_vehicle_id` (`vehicle_id`),
  KEY `idx_pa_status` (`status`),
  KEY `idx_pa_created_at` (`created_at`),
  CONSTRAINT `fk_pa_seller_user` FOREIGN KEY (`seller_user_id`) REFERENCES `tbl_users` (`id`),
  CONSTRAINT `fk_pa_vehicle` FOREIGN KEY (`vehicle_id`) REFERENCES `tbl_cars` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

