INSERT INTO `tbl_cars` VALUES (1,84,'A8','Audi',5,NULL,'1231231',NULL,NULL,NULL,NULL,NULL,'221(300)',NULL,NULL,NULL,NULL,'1',NULL,NULL,NULL,0,NULL,'2026-05-29 13:41:01','2026-10-14 11:25:16',1,'2026-08-13 00:00:00','no_data','2030-01-01',NULL,'2025-01-01',NULL,NULL,'13.2',1,NULL,2,5,5,6,18,NULL,2,NULL,NULL,1,NULL,NULL,8,4,NULL,NULL,2350,1825,NULL,NULL,NULL,NULL,4,1,121212,123133,NULL,NULL,NULL,NULL,NULL,1,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'4.2 quattro',6,'published',NULL,NULL,0,221,300,NULL,NULL,NULL,NULL),(2,251,'Z4 Z85 Coupé','BMW',2,NULL,'100',NULL,NULL,NULL,NULL,NULL,'340',NULL,'The BMW Z4 is a premium 2-seat roadster designed for sporty open-top driving. The current G29 generation focuses on improved comfort and long-distance usability compared to older Z4 models, while still offering strong performance—especially in the M40i version with its turbocharged inline-6 engine. It combines rear-wheel-drive dynamics, balanced weight distribution, and modern tech, making it a daily-drivable sports convertible.',NULL,NULL,'1',NULL,'http://13.51.226.81:4000/profile/carReel1780062285808.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780571784828.png','2026-05-29 13:43:46','2026-10-14 11:25:16',0,'2026-10-08 01:00:00','no_data',NULL,NULL,NULL,NULL,NULL,'12',1,NULL,1,5,3,3,8,NULL,14,NULL,NULL,2,1,NULL,8,8,NULL,NULL,1500,1415,'A',NULL,NULL,NULL,2,1,80000,75000,NULL,1304,1864,4324,0,0,0,0,NULL,NULL,NULL,NULL,NULL,1,NULL,'M',6,'published',NULL,'Full Approved',0,NULL,340,NULL,NULL,NULL,NULL),(3,81,'Alfasud','Alfa Romeo',5,NULL,'6000',NULL,NULL,NULL,'1349',NULL,'79','Wheelchair accessible,Direct/Parallel Import,Tuning','Well-maintained Alfa Romeo Alfasud 1.3 SC with original petrol engine and manual transmission. The vehicle is in good running condition and has been regularly serviced. Equipped with front-wheel drive, 5 seats, 3 doors, and a 1349 cc engine producing 79 PS of power.\r\n\r\nFeatures include anti-theft security system, spare wheel, wheelchair accessibility, and direct/parallel import documentation. Interior and exterior are in clean condition with no major mechanical issues.\r\n\r\nA great choice for collectors and enthusiasts looking for a classic Alfa Romeo with authentic driving experience.',NULL,NULL,'1',NULL,'http://13.51.226.81:4000/profile/carReel1780062702272.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780480894163.avif','2026-05-29 13:47:01','2026-10-14 11:25:16',0,'2026-10-08 01:00:00','no_data',NULL,NULL,'2024-01-01','2026-05-22',NULL,'13',1,NULL,1,1,2,6,2,NULL,14,NULL,NULL,1,2,NULL,4,5,NULL,NULL,1320,65000,'B',NULL,NULL,NULL,3,3,600000,35000,'ZAR9010000AS12345',1370,1592,3893,900,0,1,0,'CH1980001234','Alfa Romeo Alfasud 1.3 SC – Classic Vintage Sedan in Excellent Condition','2026-05-22','2026-05-23','1',1,NULL,'1.3 SC',6,'published','8 Tires','001774',0,NULL,79,NULL,NULL,NULL,NULL),(4,81,'A1 Sport','Audi',4,NULL,'3400',NULL,NULL,NULL,NULL,NULL,'355','Wheelchair accessible,Direct/Parallel Import,Racing Car,Tuning','Audi A1 Sport 1.4 TFSI Ambition S-Tronic in excellent condition. Regularly serviced and maintained with complete service history. Equipped with automatic S-Tronic transmission, front-wheel drive, parking sensors, adaptive LED headlights, and anti-theft security system.\r\n\r\nThe vehicle is accident-free, Swiss registered, recently serviced, and ready to drive. Ideal for city driving as well as long-distance travel with excellent fuel efficiency and comfort.',NULL,NULL,'2',NULL,'http://13.51.226.81:4000/profile/carReel1780063183985.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780999882425.jpg','2026-05-29 13:57:55','2026-10-14 11:25:16',0,'2026-10-08 01:00:00','no_data',NULL,NULL,'2023-04-01','2026-05-30',NULL,'34',1,NULL,1,2,2,8,14,NULL,3,NULL,NULL,1,3,NULL,5,7,NULL,NULL,1590,1140,'B',NULL,NULL,NULL,3,3,90000,45000,'WAUZZZ8X9GB123456',1461,1740,3954,1200,0,1,0,'CH-ZH-458721','Audi A1 Sport 1.4 TFSI Ambition S-Tronic – Excellent Condition','2026-05-15','2026-05-13','2',1,NULL,'1.4 TFSI Ambition S-Tronic',6,'published','8 Tires','A1-2016-CH-001',0,NULL,355,NULL,NULL,NULL,NULL),(5,81,'DB12 Coupé','Aston Martin',5,NULL,'2000',NULL,NULL,NULL,NULL,NULL,'12','Tuning,Racing Car,Direct/Parallel Import','Stunning Aston Martin DB12 Coupé 4.0 V8 Bi-Turbo finished in metallic orange with premium black leather interior. Powered by a 680 HP twin-turbocharged V8 engine paired with an 8-speed automatic transmission.\r\n\r\nThe vehicle is accident-free, Swiss registered, regularly serviced, and equipped with advanced driver assistance systems, adaptive LED headlights, parking sensors, and premium luxury features. A perfect combination of performance, comfort, and exclusivity for enthusiasts seeking a high-end grand tourer.',NULL,NULL,'3',NULL,'http://13.51.226.81:4000/profile/carReel1780063691701.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780571784828.png','2026-05-29 14:06:56','2026-10-14 11:25:16',0,'2026-10-08 01:00:00','no_data',NULL,NULL,'2024-01-01','2026-05-30',NULL,'2345',1,NULL,2,3,5,3,14,NULL,1,NULL,NULL,1,1,NULL,6,5,NULL,NULL,1690,1450,'C',NULL,NULL,NULL,4,4,4567,23567,'WAUZZZ8X9GB1234890',12,45,67,890,0,1,0,'CH-ZH-458789','Aston Martin DB12 Coupé 4.0 V8 Bi-Turbo – Luxury Grand Tourer in Pristine Condition','2026-05-22','2026-06-02','3',1,NULL,'4.0 V8 Bi-Turbo',6,'published',NULL,'45',1,NULL,12,NULL,NULL,NULL,NULL),(6,81,'B12','BMW Alpina',4,NULL,'3455',NULL,NULL,NULL,NULL,NULL,'14','Tuning,Racing Car,Direct/Parallel Import','Stunning Aston Martin DB12 Coupé 4.0 V8 Bi-Turbo finished in metallic orange with premium black leather interior. Powered by a 680 HP twin-turbocharged V8 engine paired with an 8-speed automatic transmission. parking sensors, and premium luxury features. A perfect combination of performance, comfort, and exclusivity for enthusiasts seeking a high-end grand tourer.',NULL,NULL,'2',NULL,'http://13.51.226.81:4000/profile/carReel1780064103901.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780571784828.png','2026-05-29 14:12:29','2026-10-14 11:25:16',0,'2026-10-08 01:00:00','no_data',NULL,NULL,'2024-04-01','2026-05-30',NULL,'456',1,NULL,3,2,2,1,3,NULL,3,NULL,NULL,1,3,NULL,5,6,NULL,NULL,67899,5555,'D',NULL,NULL,NULL,3,3,2333,876,'jqdgiwlqudt78',566,78,908,333,1,1,0,'3qw4234unkj','Stunning Aston Martin DB12 Coupé 4.0 V8 Bi-Turbo finished in metallic orange with premium black leather interior. Powered by a 680 HP twin-turbocharged V8 engine paired with an 8-speed automatic transmission.\r\n\r\nThe vehicle is accident-free, Swiss registered, regularly serviced, and equipped with advanced driver assistance systems, adaptive LED headlights, parking sensors, and premium luxury features. A perfect combination of performance, comfort, and exclusivity for enthusiasts seeking a high-end grand tourer.','2026-05-28','2026-06-06','3',1,NULL,'5.7 V12 lang',6,'published',NULL,'43',0,NULL,14,NULL,NULL,NULL,NULL),(7,236,'1er Reihe E87','BMW',4,NULL,'120000',NULL,NULL,NULL,NULL,NULL,'200',NULL,NULL,NULL,NULL,'3',NULL,NULL,NULL,0,NULL,'2026-05-29 17:15:43','2026-10-14 11:25:16',1,'2026-08-13 00:00:00','no_data',NULL,NULL,'2026-01-01',NULL,NULL,'200',1,NULL,1,1,3,3,5,NULL,2,NULL,NULL,2,3,NULL,6,6,NULL,NULL,0,0,'A',NULL,NULL,NULL,2,1,12000,50000,'111',200,200,200,200,1,0,1,'111',NULL,NULL,NULL,NULL,NULL,NULL,'116d',6,'published',NULL,'120010',0,NULL,200,NULL,NULL,NULL,NULL),(8,236,'4er Reihe F83 Cabrio','BMW',NULL,NULL,'80000',NULL,NULL,NULL,NULL,NULL,'0',NULL,'testtest\n',NULL,NULL,'3',NULL,NULL,NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780571784828.png','2026-05-31 19:49:12','2026-10-07 12:04:24',1,'2026-08-13 00:00:00','no_data',NULL,NULL,'2012-11-01',NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1',NULL,NULL,NULL,NULL,1,120000,50000,NULL,1760,1940,4890,500,1,0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'M4',4,'draft','Detail8Tires','WDD1760421J0768',0,NULL,0,NULL,NULL,NULL,NULL),(9,250,'i7 G70','BMW',5,NULL,'1500',NULL,NULL,NULL,'1968',NULL,'544','Wheelchair accessible,Direct/Parallel Import,Racing Car,Tuning','**Vehicle Description (Long):**\r\n\r\nThe BMW i7 is a flagship luxury all-electric sedan that combines premium comfort, advanced technology, and high-performance electric mobility. Built on the BMW 7 Series platform, it features a spacious executive-class cabin with high-quality materials, extensive rear-seat amenities, and cutting-edge infotainment systems. The vehicle is powered by a high-capacity lithium-ion battery and one or more electric motors, delivering smooth, quiet acceleration and long driving range while producing zero tailpipe emissions. Advanced driver-assistance and safety systems support comfortable long-distance travel, while features such as adaptive air suspension, all-wheel drive (on applicable models), and intelligent energy management enhance driving dynamics and efficiency. Designed for both chauffeur-driven and owner-driven use, the BMW i7 represents BMW\'s top-tier electric luxury offering, emphasizing sustainability, innovation, comfort, and premium craftsmanship.',NULL,NULL,'2',NULL,'http://13.51.226.81:4000/profile/carReel1780296637946.mp4',NULL,1,'http://13.51.226.81:4000/profile/profileReelThumbnail1780480033291.jpg','2026-06-01 06:46:11','2026-10-14 11:25:16',0,NULL,'valid','2032-06-24',NULL,'2019-01-01','2030-06-24',NULL,'19.6',1,NULL,3,5,3,6,8,NULL,14,NULL,NULL,1,1,NULL,0,7,NULL,NULL,3250,2640,'A',NULL,NULL,NULL,5,3,175000,1699000,'WVWZZZAUZGP532394',1544,1950,5391,2000,1,1,1,'AD1234G',NULL,'2026-04-06','2033-11-24','3',NULL,NULL,'xDrive60',6,'published',NULL,'1VE616, 1VE971, 1VF451, 1VF452, 1VF453, 1VF454, 1VF455, 1VF643, 1VF728, 1VF729, 1VF730, 1VF731, 1VF732',1,NULL,544,NULL,NULL,NULL,NULL),(10,250,'Continental GT','Bentley',5,NULL,'12000',NULL,NULL,NULL,'1968',NULL,'550','Wheelchair accessible,Direct/Parallel Import,Racing Car,Tuning','The Bentley Continental GT is a high-performance luxury grand tourer designed to deliver exceptional comfort, refinement, and driving dynamics. Handcrafted in the United Kingdom, it combines elegant styling with advanced engineering and premium materials throughout the cabin. The Continental GT is powered by a twin-turbocharged V8 engine (or other powertrains depending on variant), paired with an 8-speed dual-clutch automatic transmission and all-wheel-drive system. Its interior features hand-stitched leather upholstery, real wood veneers, advanced infotainment systems, and a range of driver-assistance technologies. Adaptive air suspension and sophisticated chassis systems provide a balance between sporty handling and long-distance touring comfort. The Continental GT is recognized as one of the world\'s premier luxury performance coupes, offering exclusivity, craftsmanship, and effortless high-speed capability.',NULL,NULL,'3',NULL,'http://13.51.226.81:4000/profile/carReel1780297696789.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780480894163.avif','2026-06-01 07:01:54','2026-10-14 11:25:16',1,'2026-09-30 13:21:49','no_data',NULL,NULL,'2020-02-01','2024-05-14',NULL,'12.6',1,NULL,1,3,5,3,13,NULL,14,NULL,NULL,2,2,NULL,8,8,NULL,NULL,2750,2165,'A',NULL,NULL,NULL,5,5,350500,367500,'WVWZZZAUZGP532394',1405,1966,4850,0,1,0,1,'WVWZZZAUZGP532394',NULL,'2023-02-02','2035-02-14','3',NULL,NULL,'6.0 W12 Speed Edition 12',6,'published','8 Tires','1VE616, 1VE971, 1VF451, 1VF452, 1VF453, 1VF454, 1VF455, 1VF643, 1VF728, 1VF729, 1VF730, 1VF731, 1VF732',1,NULL,550,NULL,NULL,NULL,NULL),(11,250,'DB12 Coupé','Aston Martin',5,NULL,'100',NULL,NULL,NULL,NULL,NULL,'680',NULL,'The Aston Martin DB12 is a next-generation luxury grand touring coupe that combines British craftsmanship, advanced technology, and high-performance engineering. Powered by a 4.0-litre twin-turbocharged V8 engine producing 680 horsepower, it delivers rapid acceleration and exceptional high-speed capability while maintaining refinement suitable for long-distance touring. The DB12 features a redesigned chassis, adaptive suspension system, electronic rear differential, and sophisticated driving dynamics technologies that enhance both comfort and handling. Inside, the cabin offers hand-finished leather upholstery, premium materials, a modern touchscreen infotainment system, and advanced driver-assistance features. Positioned between a luxury GT and a supercar, the DB12 is designed to provide exclusivity, elegance, everyday usability, and exhilarating performance in a single package.',NULL,NULL,'1',NULL,'http://13.51.226.81:4000/profile/carReel1780298556592.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780571784828.png','2026-06-01 07:20:32','2026-10-14 11:25:16',1,'2026-09-30 13:21:49','no_data',NULL,NULL,'2025-01-01','2026-04-14',NULL,'12',1,NULL,1,3,5,3,11,NULL,14,NULL,NULL,2,1,NULL,8,8,NULL,NULL,2325,1788,'A',NULL,NULL,NULL,5,3,285000,279000,'WWASD123456789FD',1295,1980,4725,0,0,0,0,'DK4321W',NULL,'2026-05-11','2038-10-19','3',NULL,NULL,'4.0 V8 Bi-Turbo',6,'published',NULL,'Full Approved',1,NULL,680,NULL,NULL,NULL,NULL),(12,250,'MCPura Cielo','Maserati',2,NULL,'100',NULL,'Ipsam pariatur Cum',NULL,NULL,NULL,'350(670)','[]','The Maserati MCPura Cielo is Maserati’s flagship convertible supercar, combining performance, innovation, and Italian luxury. Built on a lightweight carbon-fibre monocoque chassis, it offers exceptional rigidity and handling. Power comes from a 3.0-litre twin-turbocharged Nettuno V6 engine producing 630 hp, paired with an 8-speed dual-clutch transmission and rear-wheel drive. Its retractable electrochromic glass roof can switch between transparent and opaque modes, providing both open-air and coupe-style driving. Advanced aerodynamics, adaptive suspension, and race-inspired engineering deliver impressive speed and agility. The cabin features premium materials, digital displays, modern infotainment, and extensive customization options, making it an exclusive supercar that blends everyday usability with thrilling driving dynamics.',NULL,NULL,'1',NULL,'http://13.51.226.81:4000/profile/carReel1780315970712.mp4',NULL,1,'http://13.51.226.81:4000/profile/profileReelThumbnail1780571784828.png','2026-06-01 10:47:15','2026-10-14 11:25:16',0,NULL,'overdue','1985-05-16',NULL,'2007-09-14','1982-05-16','Omnis sed aliquam ea','10',1,NULL,2,5,3,8,16,NULL,14,NULL,NULL,2,1,NULL,8,8,NULL,NULL,1900,1560,'A',NULL,NULL,NULL,NULL,1,350000,340000,'ASD123456789FHS',1214,1965,4667,0,0,0,0,'SHN0786',NULL,'2026-06-01','2055-06-01','3',NULL,NULL,'3.0 V6',6,'published','','Full Approvd',0,350,670,NULL,NULL,NULL,1),(13,248,'MCPura Cielo','Maserati',2,NULL,'100',NULL,NULL,NULL,NULL,NULL,'850',NULL,'The Maserati MCPura Cielo is Maserati’s flagship open-top supercar and the convertible version of the MCPura. Built around an ultra-light carbon-fibre monocoque developed with Dallara, it combines exotic supercar performance with grand-touring comfort and Italian craftsmanship. Power comes from the 3.0-litre twin-turbocharged Nettuno V6 engine producing 630 horsepower and 720 Nm of torque',NULL,NULL,'1',NULL,NULL,NULL,1,'http://13.51.226.81:4000/profile/profileReelThumbnail1780571784828.png','2026-06-01 11:25:06','2026-10-07 13:05:32',1,'2026-06-21 00:00:00','no_data',NULL,NULL,'2023-05-01',NULL,NULL,'10',1,NULL,1,5,3,8,16,NULL,14,NULL,NULL,2,1,NULL,8,8,NULL,NULL,1900,1560,'A',NULL,NULL,NULL,2,3,5465,46564,'ADS1234567890FS',1214,1965,4667,1500,0,0,0,'SHN0786',NULL,'2026-06-01','2041-11-21','3',NULL,NULL,'3.0 V6',3,'draft',NULL,NULL,0,NULL,850,NULL,NULL,NULL,NULL),(14,250,'X5 xDrive40i','BMW',5,NULL,'55000',NULL,'Automated Manual Transmission',NULL,NULL,NULL,'250 kW (340 PS)','[]','The Mercedes-Benz G-Class Cabriolet is the convertible version of the iconic G-Wagon, combining legendary off-road capability with premium luxury and open-air driving enjoyment. Built on the renowned G-Class platform, it features a robust body-on-frame construction, advanced four-wheel-drive technology, and powerful engine options that deliver confident performance on both highways and challenging terrain. The retractable soft-top roof allows drivers to enjoy an open-air experience while maintaining the rugged character that defines the G-Wagon. Inside, the cabin is finished with high-quality leather, premium materials, digital displays, and modern infotainment technology, offering exceptional comfort and convenience. Advanced driver-assistance systems, customizable interior options, and exclusive design details enhance its appeal. The G-Class Cabriolet is positioned as an exclusive luxury SUV that blends timeless design, prestige, off-road excellence, and refined open-top motoring.',NULL,NULL,'1',NULL,'http://13.51.226.81:4000/profile/carReel1780474367044.mp4',NULL,1,'http://13.51.226.81:4000/profile/profileReelThumbnail1780480894163.avif','2026-06-01 12:03:21','2026-10-14 11:25:16',0,NULL,'overdue','2026-04-10',NULL,'2019-05-12','2023-04-10','Off-road vehicle / SUV','11',1,NULL,1,3,3,1,NULL,'Black Metallic',14,NULL,NULL,2,1,2998,12,8,NULL,NULL,3260,2250,'G',NULL,NULL,NULL,4,5,60000,56000,'WBA1234567890ABCD',1214,1965,4667,1640,0,0,0,'123.456.789',NULL,'2026-06-01','2055-06-01','3',1,NULL,'300 D',6,'published','','1AB234',0,250,340,NULL,NULL,NULL,NULL),(15,251,'Phantom','Rolls Royce',5,NULL,'5',NULL,NULL,NULL,NULL,NULL,'571',NULL,'The Rolls-Royce Phantom VIII Extended Wheelbase is the pinnacle of luxury motoring, combining exceptional craftsmanship, advanced engineering, and effortless performance. Powered by a 6.75-litre twin-turbocharged V12 petrol engine producing 571 HP and 900 Nm of torque, it delivers a remarkably smooth and quiet driving experience through an 8-speed automatic transmission and rear-wheel drive system. The extended wheelbase configuration provides outstanding rear passenger space, making it ideal for chauffeur-driven travel. The handcrafted cabin features premium leather upholstery, genuine wood veneers, bespoke interior detailing, executive rear seating, advanced climate control, and state-of-the-art infotainment systems. Rolls-Royce’s renowned air suspension and self-levelling technology create the brand’s signature “magic carpet ride,” ensuring maximum comfort on any journey. With its commanding presence, iconic Pantheon grille, coach doors, and timeless design, the Phantom represents the highest standard of automotive luxury, exclusivity, prestige, and refinement.',NULL,NULL,'1',NULL,'http://13.51.226.81:4000/profile/carReel1780395204373.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780480051870.jpg','2026-06-02 10:10:36','2026-10-14 11:25:16',0,'2026-10-08 01:00:00','no_data',NULL,NULL,'2024-08-01',NULL,NULL,'13',1,NULL,1,5,1,9,10,NULL,11,NULL,NULL,2,1,NULL,12,8,NULL,NULL,3150,2610,'G',NULL,NULL,NULL,4,3,875000,850000,'SCA689C05NUX12345',1656,2018,5982,0,0,0,0,'Dubai2025',NULL,'2024-06-01','2035-07-02','3',NULL,NULL,'6.7 V12',6,'published',NULL,'Euro 6',0,NULL,571,NULL,NULL,NULL,NULL),(16,250,'SF90 Spider','Ferrari',2,NULL,'500',NULL,NULL,NULL,NULL,NULL,'1000',NULL,'The Ferrari SF90 Spider is Ferrari’s first series-production plug-in hybrid convertible supercar, combining a 3,990 cc twin-turbocharged V8 engine with three electric motors to produce a remarkable 1,000 horsepower. Its advanced all-wheel-drive system uses two electric motors on the front axle and a third motor positioned between the engine and transmission, delivering exceptional traction and performance. The retractable hardtop opens in approximately 14 seconds, transforming the vehicle from a coupe-like supercar into an open-air roadster. Capable of accelerating from 0 to 100 km/h in just 2.5 seconds and reaching a top speed of 340 km/h, the SF90 Spider offers hypercar-level performance. The plug-in hybrid system also enables electric-only driving for short distances of up to 25 km. Inside, the cabin features a fully digital instrument cluster, premium leather and carbon-fibre finishes, advanced driver controls, and cutting-edge Ferrari technology.',NULL,NULL,'4',NULL,'http://13.51.226.81:4000/profile/carReel1780486592698.mp4',NULL,0,'http://13.51.226.81:4000/profile/profileReelThumbnail1780473350321.png','2026-06-03 11:18:02','2026-10-14 11:25:16',1,'2026-09-30 13:21:49','no_data',NULL,NULL,'2025-01-01',NULL,NULL,'6',1,NULL,9,5,5,9,6,NULL,14,NULL,NULL,2,3,NULL,8,8,NULL,NULL,2000,1670,'E',NULL,NULL,NULL,NULL,1,615000,589000,'ZFF95NLA0P0398745',1191,1973,4704,0,0,0,0,'CH-MF-2026',NULL,NULL,NULL,NULL,NULL,NULL,'4.0',6,'published',NULL,'European Whole Vehicle Type Approval',0,NULL,1000,NULL,NULL,NULL,NULL),(17,81,'146','Alfa Romeo',4,NULL,'34555',NULL,NULL,NULL,NULL,NULL,'445','Tuning','ewfwfewfewffweffewfw',NULL,NULL,'1',NULL,NULL,NULL,0,NULL,'2026-06-10 11:47:01','2026-10-14 11:25:16',1,'2026-06-25 00:00:00','no_data',NULL,NULL,'2026-01-01','2026-06-28',NULL,'44',0,NULL,1,1,5,6,14,NULL,1,NULL,NULL,1,2,NULL,5,3,NULL,NULL,567,533,'D',NULL,NULL,NULL,3,4,5444,56666,'343534xzfdw3',45,44,66,45,0,1,0,'432rsdxdxsdd','dsqdwfwefewfwe','2026-06-25','2026-10-29','2',NULL,NULL,'1.4 Twin Spark 16V',6,'published',NULL,'432sdcsc',0,NULL,445,NULL,NULL,NULL,NULL),(18,250,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-06-11 13:02:51','2026-10-07 12:04:24',1,'2026-09-30 13:21:49','no_data',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'draft',NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL),(19,250,'bolero24','mahindra 12',NULL,2020,'15','diesel','none','white',NULL,NULL,NULL,'Excellent ','Amazing Car','1200000$','2345678gff435fg',NULL,'Pune',NULL,NULL,0,NULL,'2026-06-11 13:05:09','2026-10-07 12:04:24',1,'2026-09-30 13:21:49','no_data',NULL,NULL,'2024-12-02',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NUL