DROP TABLE IF EXISTS `tbl_physical_visits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_physical_visits` (
  `id` int NOT NULL AUTO_INCREMENT,
  `car_id` int NOT NULL,
  `seller_id` int NOT NULL,
  `user_id` int DEFAULT NULL,
  `full_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `phone_number` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `visit_date` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `visit_time` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `message` text COLLATE utf8mb4_general_ci,
  `status` enum('pending','confirmed','rejected') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `rescheduled_date` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `rescheduled_time` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `seller_note` text COLLATE utf8mb4_general_ci,
  `buyer_side_status` enum('pending','confirmed','rejected','reschedule') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

