--
-- Table structure for table `tbl_plans`
--

DROP TABLE IF EXISTS `tbl_plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_plans` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `slot_count` int DEFAULT NULL,
  `plan_type` enum('basic','additional','custom','bulk') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'basic',
  `duration_type` enum('monthly','yearly','weekly') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'monthly',
  `is_public` tinyint(1) NOT NULL DEFAULT '1',
  `user_id` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

