/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_purchases` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `user_plan_id` int DEFAULT NULL,
  `plan_id` int NOT NULL,
  `purchased_slots` int NOT NULL,
  `prorated_price` decimal(10,2) NOT NULL,
  `purchase_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `payment_status` enum('pending','paid','failed') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending',
  `plan_type` enum('main','additional') COLLATE utf8mb4_general_ci DEFAULT 'main',
  `transaction_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_id` (`transaction_id`),
  KEY `fk_purchases_user_id` (`user_id`),
  KEY `fk_purchases_user_plan_id` (`user_plan_id`),
  KEY `fk_purchases_plan_id` (`plan_id`)
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
