DROP TABLE IF EXISTS `tbl_users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fullName` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `phoneNumber` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `profileImage` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `isSeller` tinyint(1) DEFAULT NULL,
  `account_type` enum('private','company') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'private',
  `commercial_register_number` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_activated` tinyint(1) NOT NULL DEFAULT '1',
  `business_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `businessCountryCode` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sellerType` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `isPhysicalVisitAllowed` tinyint(1) DEFAULT '1',
  `language` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `code` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `forgotPasswordOtp` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `legalForm` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0',
  `companyName` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `companyAddress` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `vat` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `isNotification` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=off,1=on',
  `isVerified` tinyint(1) NOT NULL DEFAULT '0',
  `fcmToken` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `countryCode` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `uid` longtext COLLATE utf8mb4_general_ci,
  `pincode` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `city` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `whatsappNumber` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `fullAddress` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tagline` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_general_ci,
  `websiteUrl` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `google_place_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `google_rating` float DEFAULT '0',
  `google_rating_updated_at` datetime DEFAULT NULL,
  `whatsappCountryCode` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `coverImage` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
