--
-- Table structure for table `tbl_vehicle_catalog_version_details`
--

DROP TABLE IF EXISTS `tbl_vehicle_catalog_version_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tbl_vehicle_catalog_version_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `version_id` bigint unsigned NOT NULL,
  `fzkey` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `raw_payload` longtext COLLATE utf8mb4_general_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `equipment_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `raw_payload_stringify_eng` longtext COLLATE utf8mb4_general_ci,
  `vin_number` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type_approval_numbers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_vehicle_version_details_fzkey` (`fzkey`),
  KEY `idx_vehicle_version_details_version_id` (`version_id`),
  CONSTRAINT `fk_vehicle_catalog_version_details_version` FOREIGN KEY (`version_id`) REFERENCES `tbl_vehicle_catalog_versions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `tbl_vehicle_catalog_version_details_chk_1` CHECK (json_valid(`equipment_payload`)),
  CONSTRAINT `tbl_vehicle_catalog_version_details_chk_2` CHECK (json_valid(`type_approval_numbers`))
) ENGINE=InnoDB AUTO_INCREMENT=1520 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

